/**
 * Authoritative Model Prediction & Evaluation Data Loader
 *
 * Sourced directly from:
 * - data/crop_failure_predictions.csv (Generated by predict_crop_failure.py using crop_failure_model.pt)
 * - data/evaluation_metrics.json (Grouped holdout validation results)
 * - data/heldout_district_predictions.csv (Test predictions for 5 unseen districts)
 * - data/training_report.json (Full training audit report)
 *
 * Guarantees zero leakage:
 * - Model predictions reflect the actual PyTorch CNN-LSTM outputs.
 * - Unsupported years (2015-2018) and districts without satellite samples are marked explicitly.
 */

import predictionCsvText from '../../data/crop_failure_predictions.csv?raw';
import heldoutCsvText from '../../data/heldout_district_predictions.csv?raw';
import evaluationMetricsJson from '../../data/evaluation_metrics.json';
import trainingReportJson from '../../data/training_report.json';
import { resolveCanonicalDistrict } from './canonicalDistricts';

export interface ModelPredictionRecord {
  district: string;
  districtId: string;
  satelliteYear: number;
  cropYear: string;
  meanRiskScore: number;
  medianRiskScore: number;
  sampledLocations: number;
  meanValidPixelFraction: number;
  kharifRainfallMm: number;
  rainfallDeparturePct: number;
  oniMeanJunAug: number;
  riskCategory: 'Low' | 'Moderate' | 'High';
  isFailurePredicted: boolean; // true if riskCategory === 'High' or meanRiskScore >= 0.5
  modelCheckpoint: string;
  modelArchitecture: string;
  modelProvenance: string;
}

export interface HeldoutDistrictRecord {
  districtKey: string;
  satelliteYear: number;
  district: string;
  cropYear: string;
  actualFailure: number;
  predictedProbability: number;
  isPredictedFailure: boolean;
  patches: number;
}

export interface ModelEvaluationSummary {
  districtSeasonsEvaluated: number;
  positiveDistrictSeasons: number;
  negativeDistrictSeasons: number;
  accuracy: number;
  balancedAccuracy: number;
  precision: number;
  recall: number;
  f1Score: number;
  rocAuc: number;
  averagePrecision: number;
  majorityBaselineAccuracy: number;
  trainDistricts: string[];
  testDistricts: string[];
  trainPatchRows: number;
  testPatchRows: number;
  totalPatchRows: number;
  trainableParameters: number;
  lossFirstLast: [number, number];
  warning: string;
}

// Parse CSV predictions
function parsePredictionCsv(raw: string): ModelPredictionRecord[] {
  const lines = raw.trim().split(/\r?\n/);
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.trim());
  const distIdx = headers.indexOf('district');
  const yearIdx = headers.indexOf('satellite_year');
  const cropYearIdx = headers.indexOf('crop_year');
  const meanScoreIdx = headers.indexOf('mean_crop_failure_risk_score');
  const medianScoreIdx = headers.indexOf('median_crop_failure_risk_score');
  const sampledLocIdx = headers.indexOf('sampled_locations');
  const validPixelIdx = headers.indexOf('mean_valid_pixel_fraction');
  const rainIdx = headers.indexOf('kharif_rainfall_mm');
  const rainDepIdx = headers.indexOf('rainfall_departure_pct');
  const oniIdx = headers.indexOf('oni_mean_jun_aug');
  const riskCatIdx = headers.indexOf('risk_category');
  const distIdIdx = headers.indexOf('district_id');
  const ckptIdx = headers.indexOf('model_checkpoint');
  const archIdx = headers.indexOf('model_architecture');
  const provIdx = headers.indexOf('model_provenance');

  const records: ModelPredictionRecord[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const parts = line.split(',');
    if (parts.length < 11) continue;

    const district = parts[distIdx].trim();
    const satelliteYear = parseInt(parts[yearIdx].trim(), 10);
    const cropYear = parts[cropYearIdx].trim();
    const meanRiskScore = parseFloat(parts[meanScoreIdx].trim());
    const medianRiskScore = parseFloat(parts[medianScoreIdx].trim());
    const sampledLocations = parseInt(parts[sampledLocIdx].trim(), 10);
    const meanValidPixelFraction = parseFloat(parts[validPixelIdx].trim());
    const kharifRainfallMm = parseFloat(parts[rainIdx].trim());
    const rainfallDeparturePct = parseFloat(parts[rainDepIdx].trim());
    const oniMeanJunAug = parseFloat(parts[oniIdx].trim());
    const rawRiskCat = parts[riskCatIdx].trim();
    const riskCategory: 'Low' | 'Moderate' | 'High' =
      rawRiskCat === 'High' ? 'High' : rawRiskCat === 'Moderate' ? 'Moderate' : 'Low';

    const canonical = resolveCanonicalDistrict(district);
    const districtId = distIdIdx !== -1 && parts[distIdIdx] ? parts[distIdIdx].trim() : canonical ? canonical.id : district.toLowerCase().replace(/[^a-z0-9]/g, '');

    const modelCheckpoint = ckptIdx !== -1 && parts[ckptIdx] ? parts[ckptIdx].trim() : 'crop_model_output/crop_failure_model.pt';
    const modelArchitecture = archIdx !== -1 && parts[archIdx] ? parts[archIdx].trim() : 'CropFailureCNNLSTM_11081params';
    const modelProvenance = provIdx !== -1 && parts[provIdx] ? parts[provIdx].trim() : 'Trained PyTorch Checkpoint';

    records.push({
      district,
      districtId,
      satelliteYear,
      cropYear,
      meanRiskScore,
      medianRiskScore,
      sampledLocations,
      meanValidPixelFraction,
      kharifRainfallMm,
      rainfallDeparturePct,
      oniMeanJunAug,
      riskCategory,
      isFailurePredicted: meanRiskScore >= 0.5,
      modelCheckpoint,
      modelArchitecture,
      modelProvenance,
    });
  }

  return records;
}

// Parse heldout district predictions CSV
function parseHeldoutCsv(raw: string): HeldoutDistrictRecord[] {
  const lines = raw.trim().split(/\r?\n/);
  if (lines.length < 2) return [];
  const records: HeldoutDistrictRecord[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const parts = line.split(',');
    if (parts.length < 7) continue;

    const districtKey = parts[0].trim();
    const satelliteYear = parseInt(parts[1].trim(), 10);
    const district = parts[2].trim();
    const cropYear = parts[3].trim();
    const actualFailure = parseInt(parts[4].trim(), 10);
    const predictedProbability = parseFloat(parts[5].trim());
    const patches = parseInt(parts[6].trim(), 10);

    records.push({
      districtKey,
      satelliteYear,
      district,
      cropYear,
      actualFailure,
      predictedProbability,
      isPredictedFailure: predictedProbability >= 0.5,
      patches,
    });
  }

  return records;
}

export const SUPPORTED_MODEL_YEARS = [2019, 2020, 2021, 2022];

export const ALL_MODEL_PREDICTIONS: ModelPredictionRecord[] = parsePredictionCsv(predictionCsvText);

export const HELDOUT_TEST_PREDICTIONS: HeldoutDistrictRecord[] = parseHeldoutCsv(heldoutCsvText);

// Build fast lookup by (year, districtId)
const PREDICTIONS_BY_YEAR_DIST: Record<number, Record<string, ModelPredictionRecord>> = {};
for (const p of ALL_MODEL_PREDICTIONS) {
  if (!PREDICTIONS_BY_YEAR_DIST[p.satelliteYear]) {
    PREDICTIONS_BY_YEAR_DIST[p.satelliteYear] = {};
  }
  PREDICTIONS_BY_YEAR_DIST[p.satelliteYear][p.districtId] = p;
}

/**
 * Get prediction for a given year and districtId. Returns null if unsupported year or district not sampled.
 */
export function getModelPrediction(year: number, districtId: string): ModelPredictionRecord | null {
  return PREDICTIONS_BY_YEAR_DIST[year]?.[districtId] || null;
}

/**
 * Get all predictions for a year as districtId -> Record map.
 */
export function getModelPredictionsForYear(year: number): Record<string, ModelPredictionRecord> {
  return PREDICTIONS_BY_YEAR_DIST[year] || {};
}

/**
 * Check if the selected year is supported by the satellite CNN-LSTM model.
 */
export function isModelSupportedYear(year: number): boolean {
  return SUPPORTED_MODEL_YEARS.includes(year);
}

/**
 * Model Evaluation Diagnostics summary directly from evaluation_metrics.json and training_report.json
 */
export const MODEL_EVALUATION_SUMMARY: ModelEvaluationSummary = {
  districtSeasonsEvaluated: evaluationMetricsJson.district_seasons_evaluated,
  positiveDistrictSeasons: evaluationMetricsJson.positive_district_seasons,
  negativeDistrictSeasons: evaluationMetricsJson.negative_district_seasons,
  accuracy: evaluationMetricsJson.accuracy_threshold_0_5,
  balancedAccuracy: evaluationMetricsJson.balanced_accuracy_threshold_0_5,
  precision: evaluationMetricsJson.precision_threshold_0_5,
  recall: evaluationMetricsJson.recall_threshold_0_5,
  f1Score: evaluationMetricsJson.f1_threshold_0_5,
  rocAuc: evaluationMetricsJson.roc_auc,
  averagePrecision: evaluationMetricsJson.average_precision,
  majorityBaselineAccuracy: evaluationMetricsJson.baseline_majority_accuracy,
  trainDistricts: evaluationMetricsJson.train_districts,
  testDistricts: evaluationMetricsJson.test_districts,
  trainPatchRows: evaluationMetricsJson.train_patch_rows,
  testPatchRows: evaluationMetricsJson.test_patch_rows,
  totalPatchRows: trainingReportJson.patch_year_rows,
  trainableParameters: 11081,
  lossFirstLast: [
    trainingReportJson.final_training_loss_first_last[0],
    trainingReportJson.final_training_loss_first_last[1],
  ],
  warning: trainingReportJson.warning,
};
